module gerald_coins (\n    input clk,\n    input rst_n,\n    input start,\n    input [63:0] n,\n    output [63:0] result,\n    output done\n);\n\n    // State declarations\n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] DIVIDE  = 2'd1;\n    localparam [1:0] COMPUTE = 2'd2;\n    localparam [1:0] FINISH  = 2'd3;\n\n    reg [1:0] state, next_state;\n    reg [63:0] current_n;\n    reg divider_start;\n    wire divider_done;\n    wire [63:0] quotient;\n    wire [1:0] remainder;\n    reg [63:0] result_reg;\n    reg done_reg;\n\n    // Instantiate divider module\n    divider_3 divider (\n        .clk(clk),\n        .rst_n(rst_n),\n        .start(divider_start),\n        .dividend(current_n),\n        .quotient(quotient),\n        .remainder(remainder),\n        .done(divider_done)\n    );\n\n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        case (state)\n            IDLE:    next_state = start ? DIVIDE : IDLE;\n            DIVIDE:  next_state = divider_done ? COMPUTE : DIVIDE;\n            COMPUTE: next_state = (remainder == 2'd0) ? DIVIDE : FINISH;\n            FINISH:  next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Datapath and control signals\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            current_n    <= 64'd0;\n            divider_start <= 1'b0;\n            result_reg    <= 64'd0;\n            done_reg      <= 1'b0;\n        end else begin\n            divider_start <= 1'b0;\n            done_reg      <= 1'b0;\n\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        current_n <= n;\n                    end\n                end\n\n                DIVIDE: begin\n                    divider_start <= 1'b1;\n                end\n\n                COMPUTE: begin\n                    if (remainder == 2'd0) begin\n                        current_n <= quotient;\n                    end\n                end\n\n                FINISH: begin\n                    result_reg <= quotient + 64'd1;\n                    done_reg   <= 1'b1;\n                end\n            endcase\n        end\n    end\n\n    assign result = result_reg;\n    assign done   = done_reg;\n\nendmodule\n\nmodule divider_3 (\n    input clk,\n    input rst_n,\n    input start,\n    input [63:0] dividend,\n    output reg [63:0] quotient,\n    output reg [1:0] remainder,\n    output reg done\n);\n\n    reg running;\n    reg [5:0] counter;\n    reg [63:0] dividend_latch;\n    reg [65:0] rem_temp; // Temporary remainder storage\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            running        <= 1'b0;\n            quotient       <= 64'd0;\n            remainder      <= 2'd0;\n            done           <= 1'b0;\n            counter        <= 6'd0;\n            dividend_latch <= 64'd0;\n            rem_temp       <= 66'd0;\n        end else begin\n            if (start && ~running) begin\n                running        <= 1'b1;\n                done           <= 1'b0;\n                counter        <= 6'd0;\n                quotient       <= 64'd0;\n                rem_temp       <= 66'd0;\n                dividend_latch <= dividend;\n            end else if (running) begin\n                if (counter < 6'd64) begin\n                    // Shift remainder and dividend\n                    rem_temp = {rem_temp[64:0], dividend_latch[63]} << 1;\n                    dividend_latch <= dividend_latch << 1;\n\n                    if (rem_temp >= 3) begin\n                        rem_temp  <= rem_temp - 3;\n                        quotient  <= {quotient[62:0], 1'b1};\n                    end else begin\n                        quotient  <= {quotient[62:0], 1'b0};\n                    end\n\n                    counter <= counter + 1;\n                end else begin\n                    remainder <= rem_temp[1:0];\n                    running   <= 1'b0;\n                    done      <= 1'b1;\n                end\n            end else begin\n                done <= 1'b0;\n            end\n        end\n    end\n\nendmodule